const $=s=>document.querySelector(s),app=$('#app'),KEY='dashain-cards-v1';let db={sessions:[],play:null,options:{}};let page='home',gameId='marriage',sessionId=null,editing=null,preview=null,notice='',timer;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(validDb(saved))db=saved;}catch{notice='Saved data could not be read. You can import a backup from History.';}
