function friendSettings(type){const meta=friendGame(type),base=select('Number of players','players',playerChoices(type),meta.default)+field('Starting chips per player','initialChips',1000,'number','min="1" max="1000000" step="1" required')+field('Rupees per chip','chipValue',1,'number','min="0" max="100000" step="0.01" required');let rules='';
 if(type==='marriage')rules=coinSettings(type,{},true)+scoreOptions('marriage',{},'play');
 else if(type==='faras')rules=field('Boot / ante','boot',2,'number','min="1" max="1000" required')+field('Maximum betting turns before showdown','turnCap',18,'number','min="3" max="100" required')+check('A-2-3 is the highest run','aceLowBest',true);
 else{rules=coinSettings(type,{},true);if(type==='callbreak')rules+=callSettingFields();if(type==='dhumbal')rules+=scoreOptions('dhumbal',{})+select('Face-card points','faceValues',[['ten','J, Q, K = 10'],['rank','J = 11, Q = 12, K = 13']],'rank')+check('Jack scores zero','jackZero',false)+check('Allow suited runs of 3+ cards','runs',true);if(type==='daharmara')rules+=select('Trump rule','trump',[['random','Random trump at deal'],['auto','First off-suit card'],['S','Spades'],['H','Hearts'],['D','Diamonds'],['C','Clubs']],'random')+check('Partners can combine consecutive trick wins','teamCapture',false);if(type==='kitti')rules+=check('A-2-3 is the highest run','aceLowBest',false)+check('Any two showings win (instead of consecutive)','anyTwo',false)+select('Reveal direction','revealDirection',[['clockwise','Clockwise'],['anticlockwise','Anti-clockwise']],'clockwise');if(type==='jutpatti')rules+=select('Cards dealt','cards',[[5,'5 cards'],[7,'7 cards']],5)+select('Wild cards','wild',[['auto','Auto: same below 4 players, higher with 4+'],['same','Indicator rank'],['above','Rank above indicator'],['none','No wild cards']],'auto');}
 return base+rules;
}
function friendNotice(type){const sizes=type==='dhumbal'?'Usual table: 2–5 players. Six or seven use house rules. ':type==='callbreak'?'Four players normally; three remove 2♥ and deal 17 cards each. ':type==='faras'?'2–17 players · three cards each. ':'';return sizes+(type==='daharmara'?'Exactly four players. Opposite seats are partners.':type==='callbreak'?'Five-round rank-stake match. Only final match results change the table balances.':type==='faras'?'Bets use table chips. Balances carry into the next deal.':POINT_GAMES.includes(type)?'The configured coin rate converts point transfers. Marriage uses net points; Call Break uses score differences; Dhumbal reverses score differences. Losses cannot exceed the table balance.':'Every player pays the boot into one pot. Winners share the pot, including their own boot. An all-player tie returns every boot.');}
function roomSetup(){const ready=!!roomService(),disabled=ready?'':'disabled';return heading('Play with friends')+'<button class="secondary" data-action="joinscores">Join live scores</button>'+`<section class="friends-intro"><p class="eyebrow">ONE CODE. ONE TABLE.</p><h2>Bring your people together.</h2><p class="muted">Create a room and share the six digits. Your friends enter them to join.</p></section>`+(roomAuth?'<button class="secondary" data-action="roomresume">Resume room</button>':'')+`<div class="friends-grid"><form id="room-create" class="panel friend-card"><span class="friend-step">01</span><h2>Create a room</h2>${select('Game','roomGame',Object.entries(FRIEND_GAMES).map(([id,g])=>[id,g.name]),friendGameId)}<p class="note" id="friend-notice">${friendNotice(friendGameId)}</p>${field('Your name','name',localStorage.getItem('dashain-nickname')||'','text','maxlength="24" autocomplete="nickname"')}<details class="friend-options"><summary>Optional rules</summary><div class="fields" id="friend-game-settings">${friendSettings(friendGameId)}</div></details><button class="friend-primary" ${disabled}>Create room</button></form><form id="room-join" class="panel friend-card"><span class="friend-step">02</span><h2>Join a room</h2><p class="muted">Enter the code your friend shared.</p><label class="code-label">Room code<input name="code" class="code-input" type="text" inputmode="numeric" autocomplete="off" pattern="[0-9]{6}" maxlength="6" placeholder="000000" required aria-label="Room code"></label>${field('Your name','name',localStorage.getItem('dashain-nickname')||'','text','maxlength="24" autocomplete="nickname"')}<button class="friend-primary" ${disabled}>Join room</button></form></div>${ready?'':'<p class="note service-pending" role="status">Friends play is getting ready. It will be available after the online service is connected.</p>'}<div id="form-error"></div>`;}
function roomLobby(){if(!roomState)return roomSetup();const type=roomState.gameType||roomState.game?.type||'marriage',meta=friendGame(type),canStart=roomState.owner&&!roomState.game&&roomState.seats.length>=meta.min;return heading(meta.name+' · Friends')+`<section class="panel friendly-lobby"><p class="eyebrow">SHARE THESE SIX DIGITS</p><div class="room-code" aria-label="Room code">${esc(roomState.code)}</div><button class="secondary" data-action="roomcopy">Copy code</button><p class="muted">Ask your friends to open Friends and enter this code.</p><div class="room-players">${roomState.seats.map((p,i)=>'<div><span class="seat-avatar">'+(i+1)+'</span><strong data-user-text>'+esc(p.name)+'</strong><span>'+(i===0?'Host · ':'')+(p.online?'Connected':'Away')+(type==='daharmara'?' · Team '+(i%2+1):'')+'</span></div>').join('')}</div><button type="button" class="secondary" data-action="editname">Change your name</button><p>${roomState.seats.length} players joined</p><p class="note">${roomState.options.initialChips??1000} <span>starting chips each</span> · Rs ${roomState.options.chipValue??1} <span>per chip</span></p><p class="note">${friendNotice(type)}</p><p class="error" ${roomError?'':'hidden'}>${esc(t(roomError))}</p><div class="actions">${roomState.owner&&!roomState.game?'<button data-action="roomstart" '+(canStart?'':'disabled')+'>Start game</button>':''}${roomState.game?'<button data-action="roomresume">Resume game</button>':''}<button class="secondary" data-action="roomleave">Back to games</button></div>${!canStart&&!roomState.game?'<p class="tiny muted">'+(type==='daharmara'?'Four players must join before dealing.':type==='callbreak'?'At least three players must join before dealing.':'At least two players must join before dealing.')+'</p>':''}</section>`;}
async function copyRoomCode(){try{await navigator.clipboard.writeText(roomState.code);}catch{const input=document.createElement('textarea');input.value=roomState.code;input.style.cssText='position:fixed;top:0;left:-9999px';document.body.append(input);input.select();const copied=document.execCommand('copy');input.remove();if(!copied){toast('Select the six digits to copy them.');return;}}toast('Room code copied.');}

