async function submitRoom(form){if(roomBusy)return;const submit=form.querySelector('button[type=submit],button:not([type])');if(submit)submit.disabled=true;try{roomBusy=true;const f=new FormData(form),server=validServer(roomService());configureServer(server);const join=form.id==='room-join';if(join&&!/^\d{6}$/.test(String(f.get('code')).trim()))throw Error('Enter the six-digit room code.');const nickname=String(f.get('name')||'').trim();if(nickname)localStorage.setItem('dashain-nickname',nickname);const response=await api(server,join?'/rooms/'+String(f.get('code')).trim()+'/join':'/rooms',{method:'POST',data:join?{name:nickname}:{name:nickname,options:readFriendOptions(form)}});roomAuth={server,...response};localStorage.setItem(ROOM_KEY,JSON.stringify(roomAuth));roomError='';roomState=await api(server,'/rooms/'+roomAuth.code,{token:roomAuth.token});page='roomlobby';render();startPolling();}catch(e){error(e);}finally{roomBusy=false;if(submit)submit.disabled=false;}}
