async function refreshRoom(force=false){if(!roomAuth||roomBusy&&!force)return;try{const next=await api(roomAuth.server,'/rooms/'+roomAuth.code,{token:roomAuth.token});const changed=!roomState||next.revision!==roomState.revision;roomState=next;roomError='';if(next.game&&page==='roomlobby')page='onlineplay';roomSelected=roomSelected.filter(id=>next.game?.hand[next.viewer].some(c=>c?.id===id));if(force||changed)render();}catch(e){const changed=roomError!==e.message;roomError=e.message;if(force)error(e);else if(changed&&page==='onlineplay'){toast(e.message);render();}}}
