async function savePlayerName(form){
 const name=String(new FormData(form).get('nickname')||'').trim(),online=form.dataset.online==='true',submit=form.querySelector('[type=submit]');
 try{if(!name||name.length>24)throw Error('Enter a name of 1–24 characters.');submit.disabled=true;
 if(online){if(roomBusy)throw Error('Please try again in a moment.');roomBusy=true;try{roomState=await api(roomAuth.server,'/rooms/'+roomAuth.code+'/action',{token:roomAuth.token,method:'POST',data:{action:{type:'rename',name},revision:roomState.revision}});roomError='';}finally{roomBusy=false;}}
 else{const g=db.play;if(g.names?.slice(1).some(n=>n.toLowerCase()===name.toLowerCase()))throw Error('That name is already at the table.');g.names=botNames(g.hand.length,name,g.names);if(g.tableId){const table=db.sessions.find(s=>s.id===g.tableId);if(table)table.names=[...g.names];}save();}
 localStorage.setItem('dashain-nickname',name);form.closest('dialog').close();render();
 }catch(e){form.querySelector('.error').textContent=t(e.message);submit.disabled=false;}
}

setInterval(()=>{if(!document.hidden&&!scoreFeed?.connected)refreshSharedScore();},10000);
let scoreLinks={};try{scoreLinks=JSON.parse(localStorage.getItem('dashain-shared-scores')||'{}');}catch{}
let sharedBusy=false,scoreEditing=false,scoreConnection='';
function scoreLink(){return scoreLinks[sessionId]||null;}
function scoreCanEdit(){return !scoreLink()||scoreLink().owner;}
function storeScoreLinks(){localStorage.setItem('dashain-shared-scores',JSON.stringify(scoreLinks));}
function sharedScoreControls(s){return scoreLink()?`${scoreLink().owner?'<button class="secondary" data-action="transferscores">Transfer ownership</button>':''}`:'<button class="secondary" data-action="sharescores">Share live scores</button>';}
function sharedScoreBanner(){const link=scoreLink();if(!link)return '';return `<section class="shared-score-banner" aria-live="polite"><div><strong>Score code · ${esc(link.code)}</strong><span>${link.owner?'You own this record':'Read only · Owner: '+esc(link.members?.find(m=>m.id===link.ownerId)?.name??'Scorekeeper')}</span><small>${scoreConnection?esc(scoreConnection):'Scores update automatically · '+(link.members?.length??1)+' joined'}</small></div><div class="score-share-actions"><button data-action="sharescorelink">Share link</button><button class="secondary" data-action="copyscorelink">Copy link</button><button class="link" data-action="copyscorecode">Copy code</button></div></section>`;}
function scorePayload(s){return {game:s.game,names:s.names,rules:s.rules,rounds:s.rounds,playTable:!!s.playTable};}
function applySharedScore(id,value){if(!value||!/^\d{6}$/.test(value.code)||!Number.isInteger(value.revision)||!value.record||!validDb({sessions:[{...value.record,id}],options:{}}))throw Error('The server returned an invalid score record.');value.record.rules=validateScoreRules(value.record.rules);const link=scoreLinks[id];Object.assign(link,{revision:value.revision,owner:!!value.owner,ownerId:value.ownerId,viewer:value.viewer,members:value.members});const index=db.sessions.findIndex(s=>s.id===id),record={...value.record,id};if(index<0)db.sessions.push(record);else db.sessions[index]=record;storeScoreLinks();}
async function createSharedScores(){if(sharedBusy)return;const s=session();if(!s||!roomService())throw Error('Connect to the online service to share scores.');sharedBusy=true;try{const server=validServer(roomService()),auth=await api(server,'/scores',{method:'POST',data:{name:localStorage.getItem('dashain-nickname')||'Scorekeeper',record:scorePayload(s)}});scoreLinks[s.id]={server,...auth};const value=await api(server,'/scores/'+auth.code,{token:auth.token});applySharedScore(s.id,value);save();render();toast('Use Share link to invite viewers, or enter the code through Join live scores.');}finally{sharedBusy=false;}}
function scoreDialog(title,body){document.querySelector('#score-dialog')?.remove();const dialog=document.createElement('dialog');dialog.id='score-dialog';dialog.className='nickname-dialog';dialog.innerHTML=`<h2>${t(title)}</h2>${body}<button type="button" class="secondary score-dialog-cancel">${t('Cancel')}</button>`;dialog.querySelector('.score-dialog-cancel').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal();return dialog;}
function openScoreJoin(){scoreDialog('Join shared scores',`<form id="score-join-form">${field('Score code','code','','text','pattern="[0-9]{6}" inputmode="numeric" maxlength="6" required')}${field('Your name','name',localStorage.getItem('dashain-nickname')||'','text','maxlength="24" required')}<p>Join to view scores. Only the owner can edit.</p><p class="error" role="alert" hidden></p><button type="submit">Join scores</button></form>`);}
async function enterSharedScore(code,name){
 const server=validServer(roomService());if(!/^\d{6}$/.test(code))throw Error('Enter the six-digit score code.');
 const existing=Object.keys(scoreLinks).find(k=>scoreLinks[k].code===code&&scoreLinks[k].server===server),id=existing??'shared-score-'+code;
 const auth=existing?scoreLinks[id]:await api(server,'/scores/'+code+'/join',{method:'POST',data:{name:name||'Guest viewer'}}),value=await api(server,'/scores/'+code,{token:auth.token});
 if(!existing)scoreLinks[id]={server,...auth};applySharedScore(id,value);sessionId=id;gameId=value.record.game;page='board';scoreEditing=false;scoreConnection='';save();render();
}
async function joinSharedScore(form){if(sharedBusy)return;sharedBusy=true;const button=form.querySelector('[type=submit]');button.disabled=true;try{const f=new FormData(form),name=String(f.get('name')).trim();await enterSharedScore(String(f.get('code')).trim(),name);localStorage.setItem('dashain-nickname',name);form.closest('dialog').close();}catch(e){const el=form.querySelector('.error');el.hidden=false;el.textContent=t(e.message);}finally{button.disabled=false;sharedBusy=false;}}

async function publishSharedScore(id=sessionId){const link=scoreLinks[id];if(!link)return;if(!link.owner)throw Error('Only the score owner can make changes.');if(sharedBusy)throw Error('Please try again in a moment.');sharedBusy=true;try{const value=await api(link.server,'/scores/'+link.code+'/action',{token:link.token,method:'POST',data:{revision:link.revision,action:{type:'update',record:scorePayload(db.sessions.find(s=>s.id===id))}}});applySharedScore(id,value);scoreConnection='';}finally{sharedBusy=false;}}
async function refreshSharedScore(){const link=scoreLink(),id=sessionId;if(!link||sharedBusy||scoreEditing||page!=='board')return;sharedBusy=true;try{const value=await api(link.server,'/scores/'+link.code,{token:link.token}),changed=value.revision!==link.revision||scoreConnection;applySharedScore(id,value);scoreConnection='';if(changed){save();render();}}catch(e){if(!scoreConnection){scoreConnection='Offline or unavailable · Showing last saved scores';render();}}finally{sharedBusy=false;}}
function openScoreTransfer(){const link=scoreLink();if(!link?.owner)throw Error('Only the score owner can make changes.');const members=(link.members??[]).filter(m=>m.id!==link.viewer);if(!members.length)throw Error('Ask another person to join using the score code first.');scoreDialog('Transfer ownership',`<form id="score-transfer-form">${select('New owner','member',members.map(m=>[m.id,esc(m.name)]),members[0].id)}<p>You will become a read-only viewer. The new owner can edit rules and rounds.</p><p class="error" role="alert" hidden></p><button type="submit">Transfer ownership</button></form>`);}
async function transferSharedScore(form){if(sharedBusy)return;const link=scoreLink();sharedBusy=true;try{const value=await api(link.server,'/scores/'+link.code+'/action',{token:link.token,method:'POST',data:{revision:link.revision,action:{type:'transfer',member:new FormData(form).get('member')}}});applySharedScore(sessionId,value);save();form.closest('dialog').close();render();}catch(e){const el=form.querySelector('.error');el.hidden=false;el.textContent=t(e.message);}finally{sharedBusy=false;}}

async function copyScoreLink(){
 const link=scoreLink();if(!link)return;const url=scoreShareUrl(link.server,link.code);
 try{await navigator.clipboard.writeText(url);toast('Score link copied. Share it in any messaging app.');}
 catch{const input=document.createElement('textarea');input.value=url;input.style.cssText='position:fixed;left:-9999px';document.body.append(input);input.select();const copied=document.execCommand('copy');input.remove();if(copied)toast('Score link copied. Share it in any messaging app.');else{const dialog=scoreDialog('Copy score link',`<label>${t('Score link')}<input readonly value="${esc(url)}"></label>`);dialog.querySelector('input').select();}}
}
async function shareScoreLink(){
 const link=scoreLink();if(!link)return;const url=scoreShareUrl(link.server,link.code);
 if(window.DashainNative?.shareScores&&window.DashainNative.shareScores(url))return;
 if(navigator.share){try{await navigator.share({title:'Dashain Cards · Live scores',text:'Follow our live scores. Open this link to join as a viewer.',url});return;}catch(e){if(e.name==='AbortError')return;}}
 await copyScoreLink();
}
let scoreLinkOpening=false;
async function openScoreLink(){
 const code=scoreCodeFromHash(location.hash);if(!code||scoreLinkOpening)return;scoreLinkOpening=true;sharedBusy=true;notice='Opening shared scores…';render();
 try{await enterSharedScore(code,localStorage.getItem('dashain-nickname')||'Guest viewer');notice='';render();}
 catch(e){notice='';page='home';render();openScoreJoin();const form=document.querySelector('#score-join-form');form.elements.code.value=code;const el=form.querySelector('.error');el.hidden=false;el.textContent=t(e.message);}
 finally{sharedBusy=false;scoreLinkOpening=false;}
}
window.addEventListener('hashchange',openScoreLink);
openScoreLink();

function pointExampleButton(key,label){return '<button type="button" class="point-example-toggle" data-action="pointexample" data-key="'+key+'" aria-label="'+esc((language==='ne'?'पत्तीको उदाहरण: ':'Card example: ')+label)+'" aria-expanded="false" aria-controls="point-example-'+key+'">⌄</button>';}
function pointExampleRow(key,label){const example=POINT_EXAMPLES[key];if(!example)return '';const visual=c=>card(c).replace('<button','<span role="img"').replace('</button>','</span>').replace(' aria-pressed="false"','');return '<tr class="point-example-row" id="point-example-'+key+'" hidden><td colspan="4"><div class="point-example-content"><div class="example-basis">'+visual(EXAMPLE_MAAL)+'<span>'+(language==='ne'?'उदाहरणको पल्टिएको माल: J♣':'Example flipped maal: J♣')+'</span></div><div class="point-example-cards" aria-label="'+esc(label)+'">'+example.cards.map(visual).join('')+'</div><p>'+esc(example[language==='ne'?'ne':'en'])+'</p></div></td></tr>';}

function showRoundCalculation(index,selected){
 const s=session(),c=explainMarriageRound(s,index),L=(en,ne)=>language==='ne'?ne:en,N=p=>esc(s.names[p]),rate=Number(c.rate).toFixed(2),status={seen:L('Seen','माल हेरेको'),unseen:L('Unseen','माल नहेरेको'),dublee:L('Seen · dublees','माल हेरेको · दुब्ली'),out:L('Sitting out','नखेलेको')};
 document.querySelector('#round-calculation-dialog')?.remove();const dialog=document.createElement('dialog');dialog.id='round-calculation-dialog';dialog.className='round-calculation-dialog';
 const heading='<header class="calculation-header"><h2>'+L('Round '+(index+1)+' · Calculation','बाजी '+(index+1)+' · हिसाब')+'</h2><button type="button" class="calc-close" aria-label="'+L('Close calculation','हिसाब बन्द गर्नुहोस्')+'">×</button></header>';
 let content='';
 if(!c.available){content='<p>'+L('The detailed inputs were not saved for this round. These are the recorded results; a full formula cannot be reconstructed.','यस बाजीको विस्तृत विवरण सुरक्षित छैन। यहाँ सुरक्षित नतिजा देखाइएको छ; पूरा हिसाब फेरि बनाउन मिल्दैन।')+'</p>'+c.scores.map((v,p)=>'<p data-user-text>'+N(p)+': '+signed(v)+' · '+money(v,s.rules)+'</p>').join('');}
 else{
 content='<p class="calculation-context">'+L('Using this table’s current rules.','यस टेबलका हालका नियमअनुसार।')+'</p><div class="calculation-overview"><p>'+L('Winner','विजेता')+': <strong data-user-text>'+(c.winner===null?L('Nobody finished','कसैले सकेन'):N(c.winner))+'</strong></p><p>'+L('Players in this round','यस बाजीका खेलाडी')+': <strong>'+c.activeCount+'</strong> · '+L('Total counted maal','गनिएको जम्मा माल')+': <strong>'+c.totalMaal+'</strong></p><p>'+L('Rate','दर')+': Rs '+rate+' '+L('per point','प्रति अंक')+'</p></div>';
 if(c.cancelled)content+='<p class="note">'+L('Cancelled deal: no game points. New fouls wait for a later winning round.','रद्द बाजीमा खेलको अंक लाग्दैन। नयाँ फाउल पछिको विजेता भएको बाजीमा लाग्छ।')+'</p>';
 if(c.unseenMaal==='murder')content+='<p class="calculation-rule">'+L('Murder: unseen players’ maal is excluded, but they still pay the unseen winning fee.','मर्डर: माल नहेरेका खेलाडीको माल गनिँदैन, तर नहेरेको शुल्क तिर्नुपर्छ।')+'</p>';
 if(c.unseenMaal==='kidnap')content+='<p class="calculation-rule">'+L('Kidnap: unseen maal moves to the winner. Transferred maal: ','किडन्याप: नहेरेको माल विजेतालाई जान्छ। सारिएको माल: ')+c.unseenMaalTransferred+'</p>';
 if(c.factor===2)content+='<p class="calculation-rule">'+L('Doubled game: maal settlement and winning fees are multiplied by 2. Carried foul amounts are added afterwards.','दोब्बर खेल: मालको हिसाब र जितको शुल्कलाई २ ले गुणा गरिन्छ। अघिका फाउल त्यसपछि जोडिन्छन्।')+'</p>';
 content+=c.players.map(p=>{let lines='';const i=p.player;
 if(c.cancelled)lines+='<p>'+L('Game points = 0 (cancelled).','खेलको अंक = ० (रद्द)।')+'</p>';
 else if(p.status==='out')lines+='<p>'+L('Sitting out: excluded from the maal total and player multiplier.','नखेलेको: मालको जम्मा र खेलाडी संख्यामा समावेश हुँदैन।')+'</p>';
 else{
 lines+='<p>'+L('Entered maal','राखिएको माल')+': '+p.enteredMaal+' · '+L('Counted maal','गनिएको माल')+': <strong>'+p.countedMaal+'</strong></p><p class="calculation-formula">'+c.activeCount+' × '+p.countedMaal+' − '+c.totalMaal+' = <strong>'+signed(p.base)+'</strong></p>';
 if(i===c.winner){const fees=c.players.filter(x=>x.player!==i&&x.status!=='out');lines+='<p>'+L('Winning fees received','जितबापत पाएको शुल्क')+': '+fees.map(x=>'<span data-user-text>'+N(x.player)+': '+x.fee+'</span>').join(' + ')+' = <strong>+'+p.received+'</strong></p>';}
 else if(c.winner!==null){const why={seen:L('Seen fee','हेरेको शुल्क'),unseen:L('Unseen fee','नहेरेको शुल्क'),dubleeExempt:L('Seen fee waived for dublees','दुब्लीमा हेरेको शुल्क छुट'),foulReplaces:L('Winning fee waived by foul rule','फाउल नियमले जितको शुल्क छुट')}[p.feeReason];lines+='<p>'+why+': '+p.feeBase+(p.feeBonus?' + '+L('dublee win bonus','दुब्ली जितको बोनस')+' '+p.feeBonus:'')+' = <strong>−'+p.fee+'</strong></p>';}
 else lines+='<p>'+L('No winner: no winning fee is charged.','विजेता छैन: जितको शुल्क लाग्दैन।')+'</p>';
 lines+='<p class="calculation-formula">('+signed(p.base)+' − '+p.fee+' + '+p.received+') × '+c.factor+' = <strong>'+signed((p.base-p.fee+p.received)*c.factor)+'</strong></p>';
 }
 const carried=c.payments.filter(f=>f.player===i||f.winner===i);if(carried.length)lines+='<div class="calculation-fouls"><strong>'+L('Carried fouls','अघिका फाउल')+'</strong>'+carried.map(f=>'<p>'+L('From round ','बाजी ')+f.round+' · <span data-user-text>'+N(f.player)+' → '+N(f.winner)+'</span> · '+f.points+' '+L('points','अंक')+'</p>').join('')+'</div>';
 const before=(p.base-p.fee+p.received)*c.factor;
 lines+='<p class="calculation-final">'+L('Final points','अन्तिम अंक')+': '+(p.foulPaid||p.foulReceived?signed(before)+' − '+p.foulPaid+' + '+p.foulReceived+' = ':'')+'<strong>'+signed(p.score)+'</strong></p><p class="calculation-formula">'+signed(p.score)+' × Rs '+rate+' = <strong>'+money(p.score,s.rules)+'</strong></p>';
 return '<details class="calculation-player" '+((selected??c.winner??0)===i?'open':'')+'><summary><span data-user-text>'+N(i)+'</span><small>'+status[p.status]+'</small><strong class="'+(p.score<0?'loss':'win')+'">'+(p.score<0?L('Pays ','तिर्ने '):p.score>0?L('Receives ','पाउने '):'')+'Rs '+Math.abs(p.amount).toFixed(2)+'</strong></summary><div>'+lines+'</div></details>';
 }).join('');
 if(c.newFouls.length)content+='<div class="note"><strong>'+L('New fouls — charged to a later winner','नयाँ फाउल — पछिको विजेतालाई तिर्ने')+'</strong>'+c.newFouls.map(f=>'<p data-user-text>'+N(f.player)+' · '+f.points+' '+L('points. Not deducted in this round.','अंक। यस बाजीमा घटाइएको छैन।')+'</p>').join('')+'</div>';
 }
 dialog.innerHTML=heading+content+'<button type="button" class="secondary calc-close">'+L('Close','बन्द गर्नुहोस्')+'</button>';dialog.querySelectorAll('.calc-close').forEach(b=>b.onclick=()=>dialog.close());dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal();if(selected!==undefined)dialog.querySelector('.calculation-player[open]')?.scrollIntoView({block:'start'});
}

document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button||button.disabled)return;const action=button.dataset.action;if(action==='selectcard'||action==='sort'||action==='sortmode')gameAudio.play('select');else if(!['drawstock','drawpile','discard','playcard','testaudio'].includes(action))gameAudio.play('tap');});

function acceptRoomFeed(value){if(!value)return;if(roomBusy||!['onlineplay','roomlobby'].includes(page)||value.code!==roomAuth?.code)return;if(roomState&&value.revision<roomState.revision)return;const changed=!roomState||value.revision!==roomState.revision||roomError;roomState=value;roomError='';roomSelected=roomSelected.filter(id=>value.game?.hand[value.viewer].some(c=>c?.id===id));if(value.game&&page==='roomlobby')page='onlineplay';if(changed)render();}
function acceptScoreFeed(value){if(!value)return;const link=scoreLink();if(!link||value.code!==link.code||sharedBusy||scoreEditing||page!=='board')return;if(value.revision<=link.revision&&!scoreConnection)return;validateScoreRules(value.record.rules);applySharedScore(sessionId,value);scoreConnection='';save();render();}
function syncRealtime(){
 const active=['roomlobby','onlineplay'].includes(page)&&roomAuth,key=active?roomAuth.server+'/rooms/'+roomAuth.code+'/'+roomAuth.token:null;
 if(roomFeed&&roomFeed.key!==key){roomFeed.close();roomFeed=null;}if(key&&!roomFeed)roomFeed=subscribe(roomAuth.server,'rooms',roomAuth.code,roomAuth.token,acceptRoomFeed);if(roomFeed?.latest&&!roomBusy&&roomFeed.latest.revision>(roomState?.revision??-1))queueMicrotask(()=>acceptRoomFeed(roomFeed?.latest));
 const link=page==='board'?scoreLink():null,scoreKey=link?link.server+'/scores/'+link.code+'/'+link.token:null;if(scoreFeed&&scoreFeed.key!==scoreKey){scoreFeed.close();scoreFeed=null;}if(scoreKey&&!scoreFeed)scoreFeed=subscribe(link.server,'scores',link.code,link.token,acceptScoreFeed);if(scoreFeed?.latest&&!sharedBusy&&!scoreEditing&&scoreFeed.latest.revision>(link?.revision??-1))queueMicrotask(()=>acceptScoreFeed(scoreFeed?.latest));
}

document.addEventListener('close',e=>{if(e.target.id==='call-round-points'&&page==='play')scheduleBot();},true);
